update public.fields set verification_status='verified_against_standard', verification_quote='Variability, in time and space, is probably the most significant aspect to be considered in the design of sampling plans. Variability determines the number of sites, number of replicates, and the frequency of sample collection. — printed p.4 / PDF p.10', verification_note='VA-verified 2026-09-08 (§4.2 Variability considerations, printed p.4 / PDF p.10) [VA] — the standard names the variable but prints no value, no minimum and no formula for it; it is an engineer_input', verified_at=now() where id='e9a871e5-a2b0-4794-b38d-3efe2d3fe009' and verification_status not in ('verified_against_standard','corrected');

