update public.fields set verification_status='verified_against_standard', verification_quote='Examples of variation in wastewater due to process variability include: [...] daily and weekly variation: particular processes, e.g. scheduled cleaning, can always occur on the same day of the week, leading to a consistent pattern of variation in the quality of the discharge [...] seasonal variation: in communities with large seasonal load changes, e.g. a holiday resort or where there is a food processing operation (fish, fruit, or vegetables), the characteristics of the sewage sludge can vary over the course of a year [...] event variation: the influent (and effluent) from sewage treatment plants varies after a rainfall event — printed p.4 / PDF p.10', verification_note='VA-verified 2026-09-08 (§4.2, printed p.4 / PDF p.10) [VA] — dashed list, joined here with [...] at the bullets; the event-variation item is quoted only as far as needed. CAVEAT: the lead-in is "Examples of variation ... include" (open list closed by the enum), and the three types co-occur while the field is a single-select (STAGED R-8, R-10)', verified_at=now() where id='4cdd8718-20f6-4a3e-abb6-3b3a39ec4fbc' and verification_status not in ('verified_against_standard','corrected');

