update public.fields set verification_status='verified_against_standard', verification_quote='Except for samples to be analysed for trace organic materials, double polyethylene bags can be used for sludge cake samples. Polyethylene, polypropylene, polycarbonate, and glass containers are satisfactory from the point of view of chemical stability when sludge sampling. | Glass containers should be used when organic constituents, e.g. pesticides, are to be determined, whereas polyethylene containers are preferable for sampling parameters of general interest, e.g. pH and dry matter. — printed p.5 / PDF p.11', verification_note='VA-verified 2026-09-08 (§5.3 Containers and sample preservation, printed p.5 / PDF p.11) [VA] — two runs from the same clause joined with " | ". The printed material list is genuinely closed ("are satisfactory"), so this enum does NOT close an open list; but the determinand-dependent choice rule (glass for organics, polyethylene for pH/dry matter, polyethylene possibly unsuitable for trace metals e.g. mercury) is printed and is NOT encoded anywhere (STAGED R-12)', verified_at=now() where id='3272495b-3315-44b6-8700-875110f1c6d8' and verification_status not in ('verified_against_standard','corrected');

