-- replicate_sampling_done — boolean, §6.2.
update public.fields set verification_status='verified_against_standard', verification_quote='In a situation where automatic sampling is to be installed, e.g. on a conveyor belt, it is preferable to establish that the point at which the samples are being taken is representative of the output from that particular part of the plant. Under these circumstances, replicate sampling should be used to assess the variability of the output stream at the proposed sampling point. This technique can be applied to liquid as well as cake sludges. — printed p.7 / PDF p.13', verification_note='VA-verified 2026-09-08 (§6.2 Replicate sampling, printed p.7 / PDF p.13) [VA] — the obligation is conditional ("In a situation where automatic sampling is to be installed" / "Under these circumstances")', verified_at=now() where id='93510e02-1315-48ff-843c-8226cde60c51' and verification_status not in ('verified_against_standard','corrected');

-- replicate_ratio_met — boolean, §6.2. FINDING: the field description restates the printed ratio wrongly.
update public.fields set verification_status='verified_against_standard', verification_quote='If occasional confirmation of the sampling performance is required, replicate sampling is ideal. This should be achieved by taking a run of 10 paired replicate samples (i.e. 20 samples) after every 40 ordinary samples. It is not possible to assess whether there has been a change in sampling behaviour until two sets of 10 paired replicate results have been obtained and compared. — printed p.7 / PDF p.13', verification_note='VA-verified 2026-09-08 (§6.2, printed p.7 / PDF p.13) [VA] — FINDING: the field description says "10 replicate samples taken for every 40 ordinary samples (1 in 20 sampled)". The printed rule is 10 PAIRED replicates, i.e. 20 samples, after every 40 ordinary samples; the string "1 in 20" appears nowhere in the standard and misstates the ratio, which is 20:40. The printed numbers 10/20/40 are carried by a bare boolean checkbox with no numeric field and no gate (STAGED R-6, R-13)', verified_at=now() where id='da97e85e-0baf-46ac-9b38-9a59269040bc' and verification_status not in ('verified_against_standard','corrected');

-- sample_type — enum, §6.1.2. This list IS genuinely closed by the printed lead-in.
update public.fields set verification_status='verified_against_standard', verification_quote='The basic types of sample which can be required are: [...] a composite sample which can be generated from either continuous or grab samples from stockpiles, sampling of liquid or cake sludges [...] a grab sample, which is taken at random from a liquid or conveyor flow of cake or from a single sample point in a stockpile. A programmed series of grab samples analysed individually, which can be liquid or cake samples, is a refinement of this technique. — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.2 Sample type, printed p.6 / PDF p.12) [VA] — items a) and b) joined with [...]. This is one of the few genuinely CLOSED lists in the document ("The basic types ... are"), so the 2-value enum is faithful', verified_at=now() where id='f81fa43e-d06b-4d3e-a30a-63c88e9f8569' and verification_status not in ('verified_against_standard','corrected');

-- sampling_mode — enum, §6.1.3 / §6.1.4.3 / §6.1.4.4 / §6.1.4.5.
update public.fields set verification_status='verified_against_standard', verification_quote='Time-basis samples can be a programmed series of grab samples that are to be analysed individually or combined into a composite sample. | In continuous sampling at regular intervals, the samples are taken uniformly throughout the whole supply of sludge, but are then grouped together into composite samples. | For this type of sampling, the sludge is regarded as a series of batches and only a proportion is selected for sampling. | This is accomplished by extracting a mass of sludge proportional to the flow rate at the sampling point at the end of each time interval. — printed p.6 and p.7 / PDF p.12 and p.13', verification_note='VA-verified 2026-09-08 (§6.1.3 time-basis printed p.6 / PDF p.12; §6.1.4.3 continuous, §6.1.4.4 intermittent-consignment, §6.1.4.5 flow-related printed p.7 / PDF p.13) [VA] — one defining run per enum value, joined with " | " in enum order; each is the opening sentence of its own sub-clause, so the 4-value enum maps 1:1 onto printed sub-clauses', verified_at=now() where id='690aad7b-17e3-4fc0-aff4-d7e00768fa8c' and verification_status not in ('verified_against_standard','corrected');

-- m — number [t], §6.1.3, input to Equation (1).
update public.fields set verification_status='verified_against_standard', verification_quote='Calculate the maximum sampling interval, t, in minutes, between taking samples when using time-based sampling, using Equation (1): [...] m is the mass, in tonnes, of the batch — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.3, Equation (1) symbol list, printed p.6 / PDF p.12) [VA] — encoded unit "t" (tonnes) matches the printed "in tonnes"; confirmed on the rendered page image', verified_at=now() where id='549fcdcd-fcad-43ae-b0cb-d8f008dbd30b' and verification_status not in ('verified_against_standard','corrected');

-- q — number [t/h], §6.1.3, input to Equation (1).
update public.fields set verification_status='verified_against_standard', verification_quote='Calculate the maximum sampling interval, t, in minutes, between taking samples when using time-based sampling, using Equation (1): [...] q is the maximum mass flow rate, in tonnes per hour — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.3, Equation (1) symbol list, printed p.6 / PDF p.12) [VA] — encoded unit "t/h" matches the printed "in tonnes per hour"; confirmed on the rendered page image', verified_at=now() where id='efa0823d-5939-4145-8464-12dd20486e13' and verification_status not in ('verified_against_standard','corrected');

-- t — number [min], §6.1.3, OUTPUT of Equation (1). data_class = derived.
update public.fields set verification_status='verified_against_standard', verification_quote='Calculate the maximum sampling interval, t, in minutes, between taking samples when using time-based sampling, using Equation (1): [...] 60 is the number of minutes per hour — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.3, printed p.6 / PDF p.12) [VA] — encoded unit "min" matches "in minutes". NOTE (#22 class): t is the output_symbol of Equation 1 yet is a hand-enterable number field; gate CR-012 "t > 0" is a tautology over it (STAGED R-7)', verified_at=now() where id='d32d3718-668a-4cc7-af9d-b574270f0b35' and verification_status not in ('verified_against_standard','corrected');

-- n — number, §6.1.3 + §6.1.4.2. Output of Eq.2 AND input to Eq.1.
update public.fields set verification_status='verified_against_standard', verification_quote='n is the number of samples. | To calculate the minimum sample number for taking composite samples, Equation (2) should be used — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.3 symbol list and §6.1.4.2, printed p.6 / PDF p.12) [VA] — NOTE (#22 class): n is the output_symbol of Equation 2 AND an input_symbol of Equation 1, yet is is_required=true and hand-enterable; gate CR-013 "n > 0" is a tautology over a squared expression (STAGED R-7)', verified_at=now() where id='41c84966-d850-4f16-b01c-217947548c6a' and verification_status not in ('verified_against_standard','corrected');

-- s — number, §6.1.4.2. QUOTE DELIBERATELY TRUNCATED before the Symbol-font casualty; see the note.
update public.fields set verification_status='verified_against_standard', verification_quote='s is the standard deviation estimated from test sampling | The standard deviation can be estimated by repeated collection and analysis of a large number — printed p.6 and p.7 / PDF p.12 and p.13', verification_note='VA-verified 2026-09-08 (§6.1.4.2, printed p.6 and p.7 / PDF p.12 and p.13) [VA] — the second run is quoted only as far as "a large number" ON PURPOSE: the very next token is a Symbol-font glyph that pdftotext DROPS, so the text layer reads "(W30)". Read from the rendered page image (printed p.7 / PDF p.13) the printed text is "a large number (>=30) of grab samples, e.g. at plant set-up, and checked at intervals" with the greater-than-or-equal sign. The damaged run was NOT repaired inside the quote; the fact is recorded here instead. Encoded unit "-" is correct: the standard says s is expressed in the units of the measurand', verified_at=now() where id='e904d368-03f3-42ae-ba9f-9a99ec7fffcf' and verification_status not in ('verified_against_standard','corrected');

-- E — number, §6.1.4.2.
update public.fields set verification_status='verified_against_standard', verification_quote='E is the maximum permitted error, expressed in the same units as s — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.4.2, Equation (2) symbol list, printed p.6 / PDF p.12) [VA] — encoded unit "-" is correct ("expressed in the same units as s"). The field description cites "Annex D example: E = +/-30 mg/kg dry mass" and CORRECTLY labels it an example; no gate enforces that value, and mg/kg dry mass is not carried as a field unit anywhere', verified_at=now() where id='d3d77d1b-6e94-4312-b7ec-6f2e2f3ba06a' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-13-06 "Probenahme-Methodik nach Quelle" (7 rows) ----------

-- sludge_source — enum, §6.3.3..§6.3.10 (sub-clause headings).
update public.fields set verification_status='verified_against_standard', verification_quote='Sampling from tanks and road tankers [...] Sampling from pipes [...] Sampling from open channels [...] Sampling of sludge cake from heaps and stockpiles [...] Sampling from wagons [...] Sampling from conveyor belts [...] Sampling from long piles [...] Sampling after dewatering by centrifugation — printed p.8 to p.11 / PDF p.14 to p.17', verification_note='VA-verified 2026-09-08 (§6.3.3 to §6.3.10 sub-clause headings, printed p.8-11 / PDF p.14-17) [VA] — the 11-value enum maps onto these eight headings plus the three §6.3.8 sub-cases (static belt §6.3.8.2, falling stream §6.3.8.3, moving belt manual §6.3.8.4 / mechanical §6.3.8.5), all of which are printed headings. Faithful. NOTE: this enum drives no branching anywhere — no gate and no equation reads it (STAGED R-5)', verified_at=now() where id='eaa1dd83-5da0-4538-a742-2bcc685e5478' and verification_status not in ('verified_against_standard','corrected');

-- sample_volume_adequate — boolean, §6.3.2.1.
update public.fields set verification_status='verified_against_standard', verification_quote='It should be noted that thin liquid sludges (of low solids content) require the preparation of relatively large volumes of the sampled material to provide sufficient dry matter to allow for a truly representative analysis of constituents, e.g. metals. The analyst should always be consulted as to the quantities of sludge required, and the sample reduced accordingly in the field before returning to the laboratory. — printed p.8 / PDF p.14', verification_note='VA-verified 2026-09-08 (§6.3.2.1 Liquid sludges, printed p.8 / PDF p.14) [VA] — HONEST RESIDUE: the standard prints NO sample mass or volume anywhere. §6.3.2.2 states explicitly "NOTE Little guidance can be given as to the size of samples. This is because this criterion is dependent on the variability of the sampled material and the type of analysis to be carried out." So the boolean hides no printed limit — there is none to hide — but "adequate" is defined only by the analyst, not by this standard', verified_at=now() where id='a866af03-3498-4ae3-bda5-1af7cfcb0aa9' and verification_status not in ('verified_against_standard','corrected');

-- solids_content — number [%], §6.3.5. This carries a PRINTED HARD NUMBER that no gate enforces.
update public.fields set verification_status='verified_against_standard', verification_quote='A weighted bucket or a pump should be used, depending on the solids content of the sludge. When using a pump to sample from an open channel, a solids content of up to 5 % mass fraction can be sampled, provided the velocity in the suction pipe is sufficient to keep all the particulates in suspension. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.5 Sampling from open channels, printed p.9 / PDF p.15) [VA] — FINDING: this is one of only two hard numbers in the normative body (5 % mass fraction; the other is the 5 mm screen in §7.1) and NO gate references this field at all. The limit is also scoped twice over — to pump sampling AND to open channels — while the field is unscoped. Encoded unit "%" should read "% mass fraction" (STAGED R-6, R-12)', verified_at=now() where id='c3ba7f13-65bf-42e7-9ec0-72f83ad05c2b' and verification_status not in ('verified_against_standard','corrected');

-- full_depth_sampling — boolean, §6.3.5.
update public.fields set verification_status='verified_against_standard', verification_quote='Samples should be taken across the width and depth of the channel to ensure that a representative composite sample is obtained after mixing individual samples. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.5, printed p.9 / PDF p.15) [VA] — CAVEAT: the printed sentence is about the OPEN CHANNEL only; the field description generalises it to heaps ("channel/heap"). §6.3.6 does carry a parallel obligation ("Samples should be taken throughout the depth of the heap or stockpile", printed p.9), so the generalisation is defensible but is not what §6.3.5 says (STAGED R-11)', verified_at=now() where id='57915de2-8411-421f-8d1f-6fbdbc911f1c' and verification_status not in ('verified_against_standard','corrected');

-- V — number [m3], §6.3.6, input to Equation (3).
update public.fields set verification_status='verified_against_standard', verification_quote='where V is the nominal volume, in cubic metres, of the stockpile. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.6, Equation for n_sp, printed p.9 / PDF p.15) [VA] — encoded unit "m3" matches "in cubic metres"; confirmed on the rendered page image', verified_at=now() where id='bcec0f85-5170-4205-9df6-43ef0551bc52' and verification_status not in ('verified_against_standard','corrected');

-- n_sp — number, §6.3.6, OUTPUT of Equation (3). The 4..30 band is the anchor of block gate CR-017.
update public.fields set verification_status='verified_against_standard', verification_quote='A composite sample can then be prepared from a statistically significant number, nsp, of such cores. [...] The value of nsp, rounded to the nearest whole number, should lie between 4 and 30. Consult ISO 5667-12 for further guidance on core sampling. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.6, printed p.9 / PDF p.15) [VA] — read from the rendered page image. The band 4..30 IS printed in the normative body (not in an example), so the numbers are sound; the MODAL is "should lie", and inclusivity of "between 4 and 30" is not stated. NOTE (#22 class): n_sp is the output_symbol of Equation 3 yet is hand-enterable, and block gate CR-017 enforces the band on every project with no scope predicate (STAGED R-3, R-7)', verified_at=now() where id='f2117d08-ce9e-4fbe-bede-bb68ee11c5bf' and verification_status not in ('verified_against_standard','corrected');

-- core_sampling_used — boolean, §6.3.6.
update public.fields set verification_status='verified_against_standard', verification_quote='If, after assessment of safety requirements, no concerns are apparent and equipment is available, core sampling can be considered as a means of obtaining samples. Samples should be taken throughout the depth of the heap or stockpile. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.6, printed p.9 / PDF p.15) [VA] — FINDING: the printed modal is "can be considered" (permissive, and doubly conditional on safety and equipment); the field description says core sampling is "preferred", which over-states the source. The clause opens "In general, sampling of sludge cake from heaps and stockpiles is prohibited by safety requirements, and is not technically required" (STAGED R-11)', verified_at=now() where id='2db65cb4-3f80-48b8-b1e3-602627650550' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-13-07 "Homogenisierung & Teilung (Vierteln)" (4 rows) ----------
-- NOTE: this worksheet has archetype='calculation' but carries NO equation and no number field — only four
-- booleans. Flagged in the STAGED file (R-14).

-- mass_reduction_required — boolean, §6.4.1.
update public.fields set verification_status='verified_against_standard', verification_quote='It is usually necessary to reduce the mass of any bulk solid sample. This results in a laboratory sample which in turn is reduced to obtain a test portion of appropriate mass. The sample reduction therefore needs to be carried out in such a way as to obtain at each stage a representative part of the sample. — printed p.11 / PDF p.17', verification_note='VA-verified 2026-09-08 (§6.4.1 General, printed p.11 / PDF p.17) [VA] — CAVEAT: §6.4 is headed "Sample homogenization and sub-sampling for sludge cakes (quartering)" and is scoped to CAKES, yet the field is is_required=true for every project including liquid-sludge ones (STAGED R-4)', verified_at=now() where id='d5ac269b-d38e-4fed-a6cd-a20f8c3a589c' and verification_status not in ('verified_against_standard','corrected');

-- quartering_performed — boolean, §6.4.1.
update public.fields set verification_status='verified_against_standard', verification_quote='The sample should be thoroughly mixed by heaping it on to a clean, flat and hard surface to form a cone. This is then turned over, e.g. with a shovel, to form a new cone, the operation being carried out three times. [...] The heap should then be divided into quarters, which should be uniform in thickness and diameter, giving due regard to the irregular shape. Diametrically opposed quarters are retained and should be recombined. The process is repeated until the final two quarters produce the required sample mass. — printed p.11 / PDF p.17', verification_note='VA-verified 2026-09-08 (§6.4.1, printed p.11 / PDF p.17) [VA] — two runs of the same clause joined with [...]; the printed "carried out three times" is the only count in the clause and is not encoded as a field. Same cake-only scope caveat as mass_reduction_required (STAGED R-4)', verified_at=now() where id='7ff66f5b-0cae-4b97-9959-ebdf6634335a' and verification_status not in ('verified_against_standard','corrected');

-- riffle_box_used — boolean, §6.4.2. FINDING: the encoded description carries an INVENTED specification.
update public.fields set verification_status='verified_against_standard', verification_quote='When samples have been dried and homogenized, devices such as riffle boxes (see Figure 1) can be used for sub-division if sufficient material exists. Where riffle boxes are used, the material should be distributed evenly across the width to ensure the sample is divided representatively. If wet samples are treated in this manner, they do not divide properly and can cause clogging. — printed p.12 / PDF p.18', verification_note='VA-verified 2026-09-08 (§6.4.2, printed p.12 / PDF p.18) [VA] — FINDING, two parts. (1) INVENTED SPEC: the field description states "riffle-box openings of nominal size at least 4x the largest material particle (Figure 1)". No such rule exists in this standard: the strings "4x", "four times", "largest particle" and "largest material" return ZERO hits over the full text layer, and Figure 1 (read as a rendered page image, printed p.12 / PDF p.18) is an undimensioned line drawing captioned only "Typical riffle box used for subdivision of samples in the laboratory". (2) INVERTED SCOPE: the description scopes riffle boxes to "gelatinous/heavy material", but the printed scope is DRIED AND HOMOGENIZED samples, and the same clause warns that wet samples "do not divide properly and can cause clogging"; §6.4.1 separately says gelatinous sludges "are unlikely to be suitably homogenized by this technique". The word "spinning" (as in "spinning rifflers") also appears nowhere in the standard (STAGED R-12)', verified_at=now() where id='f43c4359-26a3-4db4-aa25-ae4aa849d847' and verification_status not in ('verified_against_standard','corrected');

-- multiple_subsamples_required — boolean, §6.4.2.
update public.fields set verification_status='verified_against_standard', verification_quote='When two or more laboratory samples are required from a bulk sample, the sample mass should be reduced by quartering. All of the excess bulk sample rejected should be recombined at the individual division stages, mixed thoroughly and reduced again to provide a second laboratory sample. This should be repeated as necessary to provide the required number of laboratory samples. — printed p.11 / PDF p.17', verification_note='VA-verified 2026-09-08 (§6.4.2 Sample reduction to provide multiple sub-samples, printed p.11 / PDF p.17) [VA]', verified_at=now() where id='b95526db-9ba9-4c65-b0a6-74b81c58bb2e' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-13-08 "Lagerung, Sicherheit, Kennzeichnung & Bericht" (6 rows) ----------

-- time_dependent_analysis — boolean, §7.1.
update public.fields set verification_status='verified_against_standard', verification_quote='The methods of sampling can be time dependent in terms of the analytical technique to be used (e.g. pH change over time). In addition, if there is an immediate operational requirement for information, a loss of statistical confidence can be acceptable. Judgements have to be made on a situation-specific basis. — printed p.12 / PDF p.18', verification_note='VA-verified 2026-09-08 (§7.1 General, printed p.12 / PDF p.18) [VA]', verified_at=now() where id='de6872e1-cb82-49a4-b270-71090c0f5e3f' and verification_status not in ('verified_against_standard','corrected');

-- gross_solids_screened — boolean, §7.1. This carries the second (and last) printed hard number.
update public.fields set verification_status='verified_against_standard', verification_quote='For some types of liquid sludge, particularly raw sewage sludge, gross atypical solids, e.g. rags, can be removed by passing the sample through a stainless steel or plastics screen of nominal size of openings not less than 5 mm. — printed p.12 / PDF p.18', verification_note='VA-verified 2026-09-08 (§7.1, printed p.12 / PDF p.18) [VA] — FINDING: the printed "nominal size of openings not less than 5 mm" is the only other hard number in the normative body, and it is carried by a bare boolean checkbox: there is no screen-aperture field and no gate on the 5 mm figure. The obligation is also scoped ("For some types of liquid sludge, particularly raw sewage sludge") while the checkbox is not (STAGED R-6)', verified_at=now() where id='f985cc17-0524-4ba7-a445-42c48f0198c8' and verification_status not in ('verified_against_standard','corrected');

-- storage_conditions_per_iso15 — boolean, §7.2.
update public.fields set verification_status='verified_against_standard', verification_quote='Samples should be stored at the laboratory until all data are obtained and checked, in case spurious results require investigation. The storage duration and conditions of sludge samples within the laboratory are specific to the analyte(s) to be analysed. [...] Samples should be stored no longer than the maximum storage duration times. Samples should be stored in containers appropriate to the analyte(s) to be analysed, with preservatives added if necessary. For further guidance, consult ISO 5667-15:2009, Table 1. — printed p.13 / PDF p.19', verification_note='VA-verified 2026-09-08 (§7.2 Storage, printed p.13 / PDF p.19) [VA] — two runs of the same clause joined with [...]. The actual "maximum storage duration times" are NOT printed here; they live in ISO 5667-15:2009 Table 1, which is not in the library, so any concrete duration is NR-capped', verified_at=now() where id='66f84df1-1335-46f8-b5c1-4c501cfa03c8' and verification_status not in ('verified_against_standard','corrected');

-- safety_regulations_observed — boolean, §8.
update public.fields set verification_status='verified_against_standard', verification_quote='When selecting sampling locations and when sampling potentially hazardous sludge, safety and health aspects should be observed. In general, the safety advice given in other parts of ISO 5667 is relevant on many occasions when sludge is sampled (e.g. refer to ISO 5667-10:1992, Clause 6). [...] However, these guidelines cannot be substituted for the provisions of local or national health and safety regulations, which should always be carefully studied and put into effect before sampling occurs. — printed p.13 / PDF p.19', verification_note='VA-verified 2026-09-08 (§8 Safety, printed p.13 / PDF p.19) [VA] — two runs of the same clause joined with [...]. Block gate CR-022 hangs on the second run; the modal there is "should always be carefully studied", but it defers to statutory law, which is the strongest ground any block gate has in this standard (STAGED R-4)', verified_at=now() where id='fd4bde73-c977-43b2-8e21-6451fd2164cc' and verification_status not in ('verified_against_standard','corrected');

-- sample_label_complete — boolean, §9.
update public.fields set verification_status='verified_against_standard', verification_quote='Sample containers should be clearly and unambiguously marked, so that subsequent analytical results can be properly interpreted. All details relevant to the sample should be recorded on a label attached to the sample container, in addition to the results of any on-site tests carried out by the sampler (e.g. pH). [...] Labels or forms should always be completed at the time of sample collection. — printed p.13 / PDF p.19', verification_note='VA-verified 2026-09-08 (§9 Labelling and reporting, printed p.13 / PDF p.19) [VA] — two runs of the same clause joined with [...]', verified_at=now() where id='956bd0e7-aca8-49c8-a0a4-7a9de7321cf4' and verification_status not in ('verified_against_standard','corrected');

-- sample_record_field — enum, §9 a)..h). FINDING: single-select over a printed CONJUNCTION.
update public.fields set verification_status='verified_against_standard', verification_quote='The detailed form of sample report depends on the objectives of sampling. Details which should be considered for inclusion are: [...] the name of the plant [...] the sampling site (this description should be complete enough to allow another person to find the exact location without further guidance) [...] the date and time of sample collection [...] the name of the sample collector [...] the weather conditions at the time of sampling [...] the appearance of the sample [...] information on any sample preservation technique used [...] information on any specific sample storage requirements (e.g. whether refrigeration is necessary). — printed p.13 / PDF p.19', verification_note='VA-verified 2026-09-08 (§9 items a) to h), printed p.13 / PDF p.19) [VA] — the eight lettered items are joined here with [...] at each letter. FINDING: the printed list is a CONJUNCTION — one sample report contains all eight details — but the field is a single-select enum, so the engineer picks ONE of the eight. It is also is_required=true while the printed modal is the weakest in the document ("should be considered for inclusion"). Enum value "sample_identification" is mislabelled against printed item a), which reads "the name of the plant" (STAGED R-10)', verified_at=now() where id='0bf83eef-0dbd-4e14-a64f-230c3d6f74e5' and verification_status not in ('verified_against_standard','corrected');

-- ============================ SECTION B — equations (3 rows) ============================
-- All three are verification_status='imported_unverified' with a non-null source_quote and a NULL
-- verification_quote. All three DISPLAYED formulas were read off RENDERED PAGE IMAGES, because the text layer
-- flattens a fraction to numerator-line + denominator-line with no bar, and drops Symbol-font glyphs. The
-- quotes below are therefore the surrounding PROSE and symbol lists (which the text layer carries faithfully);
-- the formula itself is attested in each note from the render.

-- EQ 1 — t = (60 * m) / (q * n), §6.1.3, ws ISO-5667-13-05.
update public.equations set verification_status='verified_against_standard', verification_quote='Calculate the maximum sampling interval, t, in minutes, between taking samples when using time-based sampling, using Equation (1): [...] 60 is the number of minutes per hour; m is the mass, in tonnes, of the batch; q is the maximum mass flow rate, in tonnes per hour; n is the number of samples. — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.3 Time-basis sampling, Equation (1), printed p.6 / PDF p.12) [VA] — the DISPLAYED formula was read from the rendered page image at 150 dpi and reads t = (60 x m) / (qn), i.e. 60 x m over qn as a single fraction. The text layer flattens it to "t = 60 x m" on one line and "qn" on the next with no fraction bar, so the encoded formula could NOT have been confirmed from the extraction alone. Encoded "t = (60 * m) / (q * n)" matches the render exactly', verified_at=now() where id='b4b5c46f-2f34-4a80-aad4-54244d7f565e' and verification_status <> 'verified_against_standard';

-- EQ 2 — n = (1.96 * s / E)^2, §6.1.4.2, ws ISO-5667-13-05.
update public.equations set verification_status='verified_against_standard', verification_quote='To calculate the minimum sample number for taking composite samples, Equation (2) should be used: [...] 1,96 is the z-value (number of standard deviations from the mean) for 95 % confidence; s is the standard deviation estimated from test sampling; E is the maximum permitted error, expressed in the same units as s; n is the number of samples. — printed p.6 / PDF p.12', verification_note='VA-verified 2026-09-08 (§6.1.4.2 Number of sub-samples, Equation (2), printed p.6 / PDF p.12) [VA] — the DISPLAYED formula was read from the rendered page image and reads n = ((1,96 x s) / E) raised to the power 2, with the exponent OUTSIDE the bracket. Encoded "n = (1.96 * s / E)^2" matches; the printed comma-decimal 1,96 vs encoded 1.96 is locale only. CORRECTION to the existing source_quote: it places the Annex D worked example on "p.9". The worked example (s = 39,7; E = +/-30; n = 6,73 rounded up to 7) is on printed p.23 / PDF p.29 — printed p.9 is §6.3.5/§6.3.6. Wrong page ref, staged as R-13', verified_at=now() where id='53384ff5-d097-4d02-a69d-7a053a9ef8ba' and verification_status <> 'verified_against_standard';

-- EQ 3 — n_sp = sqrt(V) / 2, §6.3.6, ws ISO-5667-13-06.
update public.equations set verification_status='verified_against_standard', verification_quote='A composite sample can then be prepared from a statistically significant number, nsp, of such cores. Statistically, nsp is given by the equation: [...] where V is the nominal volume, in cubic metres, of the stockpile. The value of nsp, rounded to the nearest whole number, should lie between 4 and 30. — printed p.9 / PDF p.15', verification_note='VA-verified 2026-09-08 (§6.3.6, printed p.9 / PDF p.15) [VA] — the DISPLAYED formula was read from the rendered page image at 150 dpi and reads n_sp = square root of V, over 2, i.e. the radical covers V only and the 2 is the denominator. Encoded "n_sp = sqrt(V) / 2" matches. This UPGRADES the existing source_quote, which reconstructed the radical as VC and warned it had been dropped by pdftotext: the radical is now PDF-attested, so this equation is VA. (In this extraction the radical actually survives as "n sp = V" over "2", but the fraction bar does not, so a render was needed either way.)', verified_at=now() where id='a2e44a3f-fa64-45aa-94be-80f7c57ed95e' and verification_status <> 'verified_against_standard';
